    SELECT 'estepas-salinas-mediterraneas-1510', '1510', 'Estepas salinas mediterráneas (Limonietalia)', 'Salino', 'Estepas de suelos salinos pero secos, sin encharcamiento permanente, en depresiones y llanos interiores de clima duro. Dominan el albardín (Lygeum spartum), una gramínea de matas separadas y hojas punzantes, y las siemprevivas (Limonium), que en verano cubren el suelo desnudo de flores diminutas rosas y violetas. Es un paisaje de aspecto pobre que concentra un número altísimo de plantas que no crecen en ningún otro ambiente.', 1, 38.187772, -1.094446, '#2e8b57', '{"type":"MultiPolygon","coordinates":[[[[-1.103806,38.201271],[-1.103777,38.201032],[-1.103718,38.20077],[-1.103631,38.200516],[-1.103558,38.200253],[-1.103456,38.200036],[-1.103325,38.199808],[-1.103165,38.199567],[-1.102873,38.199111],[-1.102714,38.198938],[-1.102554,38.198777],[-1.102306,38.198607],[-1.102088,38.198459],[-1.101856,38.198311],[-1.101609,38.198091],[-1.101449,38.197953],[-1.101231,38.197724],[-1.101085,38.197564],[-1.100968,38.197278],[-1.100852,38.197038],[-1.100793,38.196789],[-1.100793,38.196537],[-1.100851,38.196308],[-1.100923,38.196097],[-1.100952,38.195904],[-1.100951,38.195643],[-1.100907,38.195412],[-1.100864,38.195195],[-1.100805,38.194955],[-1.100718,38.194715],[-1.100645,38.194529],[-1.100558,38.194289],[-1.100455,38.194085],[-1.100353,38.193867],[-1.100222,38.193603],[-1.100092,38.193385],[-1.099961,38.193202],[-1.099815,38.193042],[-1.09967,38.192815],[-1.099481,38.192595],[-1.099291,38.19239],[-1.099117,38.192198],[-1.098913,38.192014],[-1.098666,38.19183],[-1.098477,38.191646],[-1.098288,38.191454],[-1.098084,38.191325],[-1.097954,38.191269],[-1.097721,38.191188],[-1.097518,38.191041],[-1.097285,38.190803],[-1.097096,38.190642],[-1.096907,38.190445],[-1.096703,38.190194],[-1.096687,38.190169],[-1.096619,38.190165],[-1.096631,38.190081],[-1.096543,38.189944],[-1.096412,38.18968],[-1.09631,38.189404],[-1.096252,38.189222],[-1.096194,38.189005],[-1.096121,38.1888