    SELECT 'galerias-y-matorrales-92D0', '92D0', 'Galerías y matorrales ribereños termomediterráneos (Nerio-Tamaricetea)', 'Ribera', 'La vegetación leñosa de ramblas, arroyos y ríos de caudal irregular, que unos meses llevan agua y otros son un lecho de piedras: adelfares y tarayales. La adelfa (Nerium oleander), de hojas coriáceas y flores rosas, y los tarays (Tamarix), de ramillas finas y flores en espiga, resisten tanto las avenidas violentas como meses de sequía. Toda la adelfa es muy tóxica, incluidas hojas y ramas secas.', 0, 38.149012, -1.095592, '#2e8b57', '{"type":"MultiPolygon","coordinates":[[[[-1.135175,38.125833],[-1.135131,38.125423],[-1.134851,38.124917],[-1.134818,38.124883],[-1.13471,38.124881],[-1.134565,38.124883],[-1.134449,38.124882],[-1.134275,38.124883],[-1.134116,38.124903],[-1.133927,38.124905],[-1.133781,38.124907],[-1.133637,38.124905],[-1.133477,38.124907],[-1.133346,38.124905],[-1.133216,38.124907],[-1.133071,38.124869],[-1.132911,38.124871],[-1.132736,38.124895],[-1.132606,38.124915],[-1.13249,38.124918],[-1.132316,38.124893],[-1.132199,38.124895],[-1.132055,38.124871],[-1.131866,38.124827],[-1.131721,38.124825],[-1.13159,38.124823],[-1.131489,38.124826],[-1.131373,38.124792],[-1.131199,38.124767],[-1.131068,38.124733],[-1.130865,38.124685],[-1.130662,38.124655],[-1.130487,38.124652],[-1.130313,38.124654],[-1.130169,38.124629],[-1.130023,38.124631],[-1.129893,38.124629],[-1.129762,38.124631],[-1.129617,38.124629],[-1.129443,38.124617],[-1.129312,38.124597],[-1.129196,38.124595],[-1.129066,38.124593],[-1.128892,38.124595],[-1.128717,38.124619],[-1.128558,38.124639],[-1.128427,38.124664],[-1.128267,38.124689],[-1.128151,38.124723],[-1.127991,38.124756],[-1.127788,38.124803],[-1.127643,38.124845],[-1.127527,38.124871],[-1.127397,38.124868],[-1.12728,38.124871],[-1.127164,38.124869],[-1.127019,38.124871],[-1.126831,38.124868],[-1.126642,38.12487],[-1.126366,38.124906],[-1.126192,38.124926],[-1.126047,38.124928],[-1.125931,38.124926],[-1.125