    SELECT 'matorrales-termomediterraneos-y-5330', '5330', 'Matorrales termomediterráneos y pre-estépicos', 'Matorral', 'El matorral de las zonas más cálidas y secas, allí donde prácticamente no hiela: palmito, espino negro, lentisco, cornicales, bojas, albaidas y esparto sobre laderas pedregosas y llanos soleados. Es un matorral abierto, con suelo desnudo a la vista entre mata y mata, y con muchas especies compartidas con el norte de África. Aguanta sequías de meses y rebrota en cuanto llueve.', 0, 38.1081, -1.081096, '#daa520', '{"type":"MultiPolygon","coordinates":[[[[-1.105253,38.105508],[-1.105234,38.105398],[-1.105207,38.105314],[-1.10516,38.105211],[-1.105108,38.105135],[-1.105029,38.105049],[-1.104922,38.10496],[-1.104773,38.104862],[-1.104672,38.104804],[-1.104601,38.104773],[-1.104519,38.10474],[-1.104436,38.104713],[-1.104332,38.104681],[-1.104184,38.104643],[-1.104063,38.104609],[-1.10398,38.104586],[-1.103864,38.104553],[-1.103741,38.10452],[-1.103625,38.104488],[-1.103508,38.104455],[-1.103383,38.104418],[-1.103269,38.104385],[-1.103059,38.104324],[-1.102893,38.104278],[-1.102778,38.104243],[-1.102669,38.104206],[-1.102624,38.104191],[-1.102542,38.104163],[-1.10247,38.10413],[-1.102392,38.104092],[-1.102307,38.10404],[-1.102229,38.10398],[-1.102158,38.103918],[-1.102093,38.103853],[-1.102036,38.103787],[-1.102033,38.103783],[-1.101967,38.10369],[-1.101828,38.103508],[-1.101711,38.103347],[-1.101581,38.103184],[-1.101488,38.103056],[-1.101361,38.102893],[-1.101297,38.102818],[-1.101252,38.102766],[-1.101207,38.102718],[-1.101164,38.102675],[-1.101102,38.102617],[-1.101001,38.102525],[-1.100894,38.102433],[-1.100766,38.102331],[-1.100603,38.102204],[-1.100473,38.102101],[-1.100325,38.101983],[-1.100275,38.101944],[-1.100201,38.101892],[-1.100149,38.101848],[-1.100074,38.101794],[-1.099985,38.101736],[-1.099889,38.101677],[-1.099816,38.101641],[-1.099726,38.101603],[-1.099635,38.101568],[-1.099467,38.101508],[-1.099372,38.101473],[-1.099228,38.101424],[-1