    SELECT 'matorrales-halonitrofilos-pegano-1430', '1430', 'Matorrales halonitrófilos (Pegano-Salsoletea)', 'Matorral', 'Matorral de suelos salinos removidos y cargados de nitrógeno: bordes de camino y de cultivo, márgenes de rambla, corrales y escombreras viejas. Lo forman matas robustas de hoja gris o carnosa —orgazas, sosas, bojas y cambroneras— que rebrotan enseguida tras cualquier alteración. Aunque nace de terrenos trastocados, es vegetación propia de los ambientes áridos del sureste y a menudo el último refugio de plantas escasas.', 0, 38.133951, -1.096888, '#9acd32', '{"type":"MultiPolygon","coordinates":[[[[-1.112423,38.122664],[-1.112379,38.122537],[-1.112278,38.122482],[-1.112148,38.122389],[-1.112017,38.122378],[-1.111857,38.12238],[-1.111727,38.122378],[-1.111581,38.122367],[-1.111437,38.122369],[-1.111262,38.122366],[-1.111132,38.122391],[-1.110972,38.122389],[-1.110842,38.122413],[-1.110653,38.122469],[-1.110478,38.122507],[-1.110304,38.12254],[-1.110159,38.122583],[-1.109999,38.122621],[-1.109869,38.122641],[-1.109753,38.122666],[-1.109607,38.122687],[-1.109447,38.122724],[-1.109288,38.12278],[-1.109143,38.122814],[-1.109027,38.122871],[-1.108852,38.122918],[-1.108707,38.122965],[-1.108562,38.122985],[-1.108446,38.123019],[-1.108434,38.123019],[-1.108389,38.123032],[-1.108198,38.12306],[-1.108068,38.123081],[-1.107925,38.123098],[-1.107839,38.123103],[-1.107765,38.123107],[-1.107587,38.123106],[-1.107401,38.123095],[-1.107221,38.12308],[-1.107057,38.123062],[-1.106999,38.123053],[-1.106718,38.123037],[-1.106316,38.123115],[-1.106191,38.123144],[-1.105647,38.12331],[-1.105786,38.122696],[-1.105789,38.12268],[-1.105762,38.122674],[-1.105617,38.122609],[-1.105502,38.122542],[-1.105284,38.122451],[-1.10529,38.122422],[-1.105225,38.122391],[-1.105153,38.122308],[-1.105101,38.122231],[-1.104854,38.122152],[-1.104719,38.122111],[-1.104603,38.121906],[-1.104653,38.121743],[-1.104719,38.121719],[-1.104878,38.121651],[-1.104878,38.121596],[-1.104849,38.121461