    SELECT 'vegetacion-gipsicola-iberica-1520', '1520', 'Vegetación gipsícola ibérica (Gypsophiletalia)', 'Matorral', 'Matorral bajo y ralo que crece únicamente sobre yeso, un suelo blanquecino que forma costra y en el que casi ninguna otra planta prospera. Las que lo consiguen están especializadas en ese sustrato y muchas no viven en ningún otro sitio, de modo que cada afloramiento de yeso tiene su propia flora. No se recupera: al roturar o extraer el yeso desaparecen a la vez el suelo y lo que crecía sobre él.', 1, 38.127554, -1.133682, '#9acd32', '{"type":"MultiPolygon","coordinates":[[[[-1.137227,38.1287],[-1.137212,38.128569],[-1.136611,38.127517],[-1.135894,38.127118],[-1.135217,38.126977],[-1.13523,38.126347],[-1.135194,38.126014],[-1.135175,38.125833],[-1.135015,38.12581],[-1.134898,38.125812],[-1.134739,38.125778],[-1.134593,38.125776],[-1.134463,38.125778],[-1.134303,38.125776],[-1.134158,38.125778],[-1.134027,38.125776],[-1.133911,38.125779],[-1.133752,38.125812],[-1.133607,38.125859],[-1.133432,38.125893],[-1.133258,38.125926],[-1.133069,38.12595],[-1.132851,38.125974],[-1.132634,38.12597],[-1.13246,38.125994],[-1.1323,38.125996],[-1.132155,38.125994],[-1.131995,38.125996],[-1.131851,38.125994],[-1.131691,38.125996],[-1.13156,38.125994],[-1.131415,38.125982],[-1.131284,38.125949],[-1.131154,38.125951],[-1.131023,38.125927],[-1.130878,38.125924],[-1.130762,38.125904],[-1.130602,38.125879],[-1.130472,38.125882],[-1.130341,38.125844],[-1.130167,38.125823],[-1.130007,38.125825],[-1.129877,38.125836],[-1.129717,38.125892],[-1.129586,38.125926],[-1.129485,38.125997],[-1.129383,38.126054],[-1.129238,38.126146],[-1.129122,38.126225],[-1.129005,38.126259],[-1.128904,38.126325],[-1.128773,38.126409],[-1.128713,38.126443],[-1.129343,38.126311],[-1.129442,38.126535],[-1.129835,38.126459],[-1.130361,38.127146],[-1.130596,38.127405],[-1.130668,38.1274],[-1.132165,38.126975],[-1.13185,38.127545],[-1.131842,38.128238],[-1.131961,38.128521],[-1.132207,38.128785],[-1.1325