    SELECT 'pendientes-rocosas-calcicolas-8210', '8210', 'Pendientes rocosas calcícolas con vegetación casmofítica', 'Roquedos', 'Paredes y cortados de roca caliza en los que la vegetación no vive sobre el suelo, sino dentro de las fisuras. Son plantas de raíz larguísima y crecimiento lentísimo, agarradas a la grieta, que aprovechan el agua que escurre por la pared. Los roquedos han quedado a salvo del arado y del ganado durante milenios, y por eso concentran una proporción altísima de especies que no existen en ningún otro lugar.', 0, 38.1081, -1.081096, '#daa520', '{"type":"Polygon","coordinates":[[[-1.089244,38.107285],[-1.089186,38.107113],[-1.089099,38.106977],[-1.088998,38.106885],[-1.088896,38.106779],[-1.088795,38.106701],[-1.088693,38.106632],[-1.088578,38.106531],[-1.088476,38.106471],[-1.088374,38.106402],[-1.088258,38.10631],[-1.088143,38.106209],[-1.087997,38.106094],[-1.087882,38.105988],[-1.087795,38.10591],[-1.08765,38.105781],[-1.08752,38.105658],[-1.087433,38.105566],[-1.087346,38.105461],[-1.087288,38.10537],[-1.087201,38.105242],[-1.087114,38.105106],[-1.087057,38.104992],[-1.086956,38.104828],[-1.086898,38.104692],[-1.086796,38.104565],[-1.086738,38.104487],[-1.086608,38.104395],[-1.086478,38.104325],[-1.086274,38.104259],[-1.086158,38.104212],[-1.086028,38.104155],[-1.085912,38.104154],[-1.085752,38.104128],[-1.085622,38.104131],[-1.085462,38.104097],[-1.085346,38.10405],[-1.08523,38.103944],[-1.085172,38.103867],[-1.085144,38.10374],[-1.085144,38.10365],[-1.085173,38.103547],[-1.085231,38.103417],[-1.085319,38.103337],[-1.085435,38.103236],[-1.085536,38.103165],[-1.085667,38.103131],[-1.085783,38.103061],[-1.0859,38.10304],[-1.086001,38.10297],[-1.086132,38.102936],[-1.086233,38.102857],[-1.086292,38.10274],[-1.086379,38.102593],[-1.086393,38.102467],[-1.086393,38.102364],[-1.086394,38.10226],[-1.086394,38.102008],[-1.086366,38.101791],[-1.086337,38.101651],[-1.086308,38.101538],[-1.086279,38.101402],[-1.086251,38.101307],[-1.086221,38.101149]