INSERT INTO species (park_id, common_name, scientific_name, kingdom, family, primary_habitat, conservation_status, description, description_source, identification_tips, seasonality, image_url, image_attribution, latitude, longitude, rarity_score, rarity_basis, rarity_local, rarity_local_basis, is_featured, is_visible, hidden_reason, source, taxon_phylum, taxon_class, taxon_order, taxon_family, taxon_genus, iucn_global, spain_status, murcia_status, review_note, eidos_taxonid, gbif_species_key, zepa_site_code, is_migratory, site_presence)
SELECT pk.id, s.common_name, s.scientific_name, s.kingdom, s.family, s.primary_habitat, s.conservation_status, s.description, s.description_source, s.identification_tips, s.seasonality, s.image_url, s.image_attribution, s.latitude, s.longitude, s.rarity_score, s.rarity_basis, s.rarity_local, s.rarity_local_basis, s.is_featured, s.is_visible, s.hidden_reason, s.source, s.taxon_phylum, s.taxon_class, s.taxon_order, s.taxon_family, s.taxon_genus, s.iucn_global, s.spain_status, s.murcia_status, s.review_note, s.eidos_taxonid, s.gbif_species_key, s.zepa_site_code, s.is_migratory, s.site_presence
FROM parks pk JOIN (
    SELECT 'Uña de gato' common_name, 'Sedum sediforme' scientific_name, 'flora' kingdom, 'Planta suculenta' family, 'Prados calcáreos del Alysso-Sedion albi' primary_habitat, 'No catalogada' conservation_status, 'Crasulácea perenne de hojas suculentas puntiagudas y flores amarillo-verdosas, muy extendida por Murcia en repisas rocosas y prados calcáreos; especie característica del hábitat prioritario.' description, NULL description_source, 'Hojas carnosas puntiagudas; Inflorescencia amarillo pálido; Coloniza repisas y suelos esqueléticos' identification_tips, 'Verano' seasonality, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sedum_sediforme_hojas.jpg?width=1280' image_url, 'autor no indicado (CC BY-SA 3.0) · Wikimedia Commons' image_attribution, NULL latitude, NULL longitude, 1 rarity_score, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}' rarity_basis, 1 rarity_local, NULL rarity_local_basis, 0 is_featured, 1 is_visible, NULL hidden_reason, 'GBIF: 5 ocurrencias dentro de los polígonos de hábitat del espacio (5 hábitats; barrido de 2026-08-22); Atlas y Manual de los Hábitats de España (MITECO, 2005): especie característica de alguno de los HIC cartografiados aquí; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas' source, 'Tracheophyta' taxon_phylum, 'Magnoliopsida' taxon_class, 'Saxifragales' taxon_order, 'Crassulaceae' taxon_family, 'Sedum' taxon_genus, 'No evaluada específicamente en la Lista Roja mundial de la UICN (especie muy común)' iucn_global, 'No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE' spain_status, 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)' murcia_status, NULL review_note, NULL eidos_taxonid, 4201784 gbif_species_key, NULL zepa_site_code, NULL is_migratory, NULL site_presence
    UNION ALL
    SELECT 'Sosa alacranera', 'Arthrocnemum macrostachyum', 'flora', 'Planta suculenta', 'Saladares y marismas con encharcamiento salino prolongado', 'No catalogada', 'Planta sin hojas aparentes: sus tallos son cilíndricos, carnosos y divididos en segmentos que parecen articulaciones. Vive donde la sal se acumula y en otoño se tiñe de tonos rojizos y anaranjados que cambian el color de todo el saladar.', NULL, 'Tallos carnosos articulados, como collares de cuentas; Sin hojas visibles; Vira a rojo y naranja en otoño', 'Verano y otoño', 'https://commons.wikimedia.org/wiki/Special:FilePath/Arthrocnemum_macrostachyum_2LaMata.jpg?width=1280', 'Javier martin (Public domain) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, NULL, 0, 1, NULL, 'GBIF: 4 ocurrencias dentro de los polígonos de hábitat del espacio (5 hábitats; barrido de 2026-08-22); Atlas y Manual de los Hábitats de España (MITECO, 2005): especie característica de alguno de los HIC cartografiados aquí; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Magnoliopsida', 'Caryophyllales', 'Amaranthaceae', 'Arthrocnemum', 'No evaluada específicamente en la Lista Roja mundial de la UICN (especie común)', 'No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 33034, 9417609, NULL, NULL, NULL
    UNION ALL
    SELECT 'Pino carrasco', 'Pinus halepensis', 'flora', 'Conífera', 'Laderas secas y soleadas sobre calizas y margas, en clima mediterráneo cálido', 'LC', 'Pino de copa clara e irregular y follaje de un verde pálido, el más resistente a la sequía y a los suelos pobres de los pinos ibéricos. Sus piñas, alargadas y asimétricas, quedan colgadas años en la rama y liberan las semillas tras los incendios, lo que le permite recolonizar rápido.', NULL, 'Copa irregular y poco densa, de verde claro; Piñas asimétricas y persistentes, apuntando hacia atrás; Corteza clara y agrietada, rojiza en las ramas jóvenes', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Pino_secolare_-_Castelleone_di_Suasa.JPG?width=1280', 'Accurimbono (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, NULL, 0, 1, NULL, 'GBIF: 4 ocurrencias dentro de los polígonos de hábitat del espacio (5 hábitats; barrido de 2026-08-22); Atlas y Manual de los Hábitats de España (MITECO, 2005): especie característica de alguno de los HIC cartografiados aquí; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Pinopsida', 'Pinales', 'Pinaceae', 'Pinus', 'LC', 'No catalogada (especie forestal común)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 7118, 5285604, NULL, NULL, NULL
    UNION ALL
    SELECT 'Sosa jabonera', 'Sarcocornia fruticosa', 'flora', 'Planta suculenta', 'Saladares con encharcamiento salino frecuente', 'No catalogada', 'Planta de tallos suculentos y articulados, de base leñosa y porte erguido, que forma matas densas en el saladar. Como su parienta la sosa alacranera, es difícil de separar a simple vista: la clave está en el porte y en la longitud de los segmentos. En otoño toma tonos rojizos.', NULL, 'Tallos verdes articulados, erguidos y ramificados; Base leñosa, no herbácea; Cambia a tonos rojizos al final del verano', 'Verano y otoño', 'https://commons.wikimedia.org/wiki/Special:FilePath/Sarcocornia_fruticosa.jpg?width=1280', 'Hans Hillewaert (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, NULL, 0, 1, NULL, 'GBIF: 4 ocurrencias dentro de los polígonos de hábitat del espacio (5 hábitats; barrido de 2026-08-22); Atlas y Manual de los Hábitats de España (MITECO, 2005): especie característica de alguno de los HIC cartografiados aquí; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Magnoliopsida', 'Caryophyllales', 'Amaranthaceae', 'Sarcocornia', 'No evaluada específicamente en la Lista Roja mundial de la UICN (especie común)', 'No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 33125, 3083613, NULL, NULL, NULL
    UNION ALL
    SELECT 'Sosa fina', 'Suaeda vera', 'flora', 'Mata', 'Bordes de saladar y suelos salinos algo más secos y elevados', 'No catalogada', 'Mata leñosa de hojas carnosas, cilíndricas y de un verde azulado, que ocupa la orla algo más alta y seca del saladar. Se diferencia de sus vecinas en que sí tiene hojas bien visibles y no tallos articulados. Sus flores son minúsculas y verdosas, en las axilas de las hojas.', NULL, 'Hojas carnosas y cilíndricas, verde azuladas; Base leñosa y ramificada, no herbácea; En la parte más seca y alta del saladar', 'Verano', 'https://commons.wikimedia.org/wiki/Special:FilePath/Suaeda_vera.JPG?width=1280', 'Xemenendura (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, NULL, 0, 1, NULL, 'GBIF: 4 ocurrencias dentro de los polígonos de hábitat del espacio (4 hábitats; barrido de 2026-08-22); Atlas y Manual de los Hábitats de España (MITECO, 2005): especie característica de alguno de los HIC cartografiados aquí; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Magnoliopsida', 'Caryophyllales', 'Amaranthaceae', 'Suaeda', 'No evaluada específicamente en la Lista Roja mundial de la UICN (especie común)', 'No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 8507, 6035538, NULL, NULL, NULL
    UNION ALL
    SELECT 'Lagartija colirroja', 'Acanthodactylus erythrurus', 'fauna', 'Reptil', 'Matorral litoral y laderas secas', 'Protegida (LESRPE)', 'Lagartija de suelos arenosos, de cuerpo aplanado y dedos con escamas laterales en forma de peine que le sirven de raqueta sobre la arena suelta. Los jóvenes tienen la cola y las patas traseras de un rojo intenso que se apaga en los adultos.', NULL, 'Dedos con flecos de escamas a los lados, como peines; Jóvenes con cola y patas traseras rojo intenso; Cuerpo aplanado, con rayas y ocelos claros en el dorso', 'Primavera a otoño', 'https://commons.wikimedia.org/wiki/Special:FilePath/Benny_Trapp_Acanthodactylus_erythrurus.jpg?width=1280', 'Benny Trapp (CC BY 3.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"En régimen de protección especial","norma":"Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011","ambito":"España"}', 0, 1, NULL, 'GBIF: 3 ocurrencias dentro de los polígonos de hábitat del espacio (2 hábitats; barrido de 2026-08-22); Plan de gestión integral de los relieves y cuencas centro-orientales, volumen II §1.2 (Decreto n.º 252/2022, BORM n.º 38 de 16.02.2023, supl. 6): la norma la enumera en el inventario conjunto del Paisaje Protegido, la ZEPA ES0000195 y la ZEC ES6200005 «Humedal del Ajauque y Rambla Salada», que el volumen II trata como un solo espacio protegido; la ZEPA y el Paisaje Protegido comparten perímetro (1.621,9 ha) y la ZEC (895,6 ha) queda dentro; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Reptilia', 'Squamata', 'Lacertidae', 'Acanthodactylus', 'LC', 'LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 11220, 5226733, NULL, NULL, NULL
    UNION ALL
    SELECT 'Albardín brezo', 'Frankenia corymbosa', 'flora', 'Mata', 'Estepas salinas, saladares y suelos margosos con sal', 'No catalogada', 'Mata baja y muy ramificada, de hojas diminutas y enrolladas que a menudo aparecen cubiertas de una costra blanca: son cristales de sal que la planta expulsa por glándulas especializadas. Sus flores son rosadas y pequeñas, apiñadas en el extremo de las ramas.', NULL, 'Costra blanca de sal cristalizada sobre las hojas; Hojas minúsculas y enrolladas, casi como escamas; Flores rosadas pequeñas agrupadas en el extremo', 'Primavera y verano', 'https://inaturalist-open-data.s3.amazonaws.com/photos/464713930/original.jpeg', 'Rafael Medina (CC BY 4.0) · GBIF', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, NULL, 0, 1, NULL, 'GBIF: 2 ocurrencias dentro de los polígonos de hábitat del espacio (2 hábitats; barrido de 2026-08-22); Atlas y Manual de los Hábitats de España (MITECO, 2005): especie característica de alguno de los HIC cartografiados aquí; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Magnoliopsida', 'Caryophyllales', 'Frankeniaceae', 'Frankenia', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 4615, 3873636, NULL, NULL, NULL
    UNION ALL
    SELECT 'Cambrón', 'Lycium intricatum', 'flora', 'Arbusto', 'Matorral costero y suelos salinos y nitrificados de clima cálido', 'Interés especial', 'Arbusto de ramas enmarañadas y espinosas, con hojitas carnosas agrupadas en manojos. Sus flores son pequeñas, tubulares y de color violeta pálido, y da bayas rojas que comen muchas aves. Forma setos impenetrables que dan refugio a pájaros y reptiles.', NULL, 'Ramas enredadas entre sí y terminadas en espina; Hojas carnosas en manojitos a lo largo de la rama; Bayas rojas pequeñas y flores tubulares violáceas', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Lycium_intrincatum_(flor).JPG?width=1280', 'ANE (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 3, NULL, 3, '{"categoria":"Especies de interés especial","norma":"Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.","ambito":"Región de Murcia"}', 0, 1, NULL, 'GBIF: 2 ocurrencias dentro de los polígonos de hábitat del espacio (2 hábitats; barrido de 2026-08-22); Plan de gestión integral de los relieves y cuencas centro-orientales, volumen II §1.2 (Decreto n.º 252/2022, BORM n.º 38 de 16.02.2023, supl. 6): la norma la enumera en el inventario conjunto del Paisaje Protegido, la ZEPA ES0000195 y la ZEC ES6200005 «Humedal del Ajauque y Rambla Salada», que el volumen II trata como un solo espacio protegido; la ZEPA y el Paisaje Protegido comparten perímetro (1.621,9 ha) y la ZEC (895,6 ha) queda dentro, con la categoría «De Interés Especial (Catálogo Regional de especies amenazadas de la Región de Murcia)»; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Tracheophyta', 'Magnoliopsida', 'Solanales', 'Solanaceae', 'Lycium', 'NE (no evaluada a nivel global)', 'No confirmada presencia en la Lista Roja de la Flora Vascular Española 2008', 'Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)', NULL, 5923, 3796884, NULL, NULL, NULL
