    SELECT 'Bayón', 'Osyris lanceolata', 'flora', 'Arbusto', 'Matorral alto, sabinares y laderas secas sobre suelo pedregoso', 'Interés especial', 'Arbusto de ramas verdes y erguidas con hojas estrechas y coriáceas. Es hemiparásito: fabrica su propio alimento pero además conecta sus raíces a las de otras plantas para robarles agua y sales. Sus frutos son bayas rojas o anaranjadas muy vistosas.', NULL, 'Ramas verdes y erectas, de aspecto escobiforme; Bayas rojo anaranjado brillantes al madurar; Hojas estrechas, duras y de punta aguda', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Osyris_lanceolata.JPG?width=1280', 'Xemenendura (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 3, NULL, 3, '{"categoria":"Especies de interés especial","norma":"Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.","ambito":"Región de Murcia"}', 0, 1, NULL, 'GBIF: 1 ocurrencia dentro de los polígonos de hábitat del espacio (1 hábitat; barrido de 2026-08-22); EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Tracheophyta', 'Magnoliopsida', 'Santalales', 'Santalaceae', 'Osyris', 'LC (Preocupación menor)', 'No localizada en la Lista Roja de la Flora Vascular Española 2008 (pendiente de confirmar)', 'Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)', NULL, 6882, 7473922, NULL, NULL, NULL
