    SELECT 'Salamanquesa común', 'Tarentola mauritanica', 'fauna', 'Reptil', 'Pendientes rocosas calcícolas con vegetación casmofítica', 'Protegida (LESRPE)', 'Gecko robusto de piel tuberculada, activo al anochecer sobre roquedos, muros y cortados, donde caza insectos atraídos por la luz.', NULL, 'Piel rugosa con tubérculos; Activa al atardecer; Trepa por rocas y muros', 'Todo el año', 'https://inaturalist-open-data.s3.amazonaws.com/photos/605672084/original.jpg', 'jrodben (CC BY-NC 4.0) · GBIF', NULL, NULL, 2, '{"categoria":"LESRPE (RD 139/2011)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"En régimen de protección especial","norma":"Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011","ambito":"España"}', 0, 1, NULL, 'GBIF: 1 ocurrencia dentro de los polígonos de hábitat del espacio (2 hábitats; barrido de 2026-08-22); Plan de gestión integral de los relieves y cuencas centro-orientales, volumen II §1.2 (Decreto n.º 252/2022, BORM n.º 38 de 16.02.2023, supl. 6): la norma la enumera en el inventario conjunto del Paisaje Protegido, la ZEPA ES0000195 y la ZEC ES6200005 «Humedal del Ajauque y Rambla Salada», que el volumen II trata como un solo espacio protegido; la ZEPA y el Paisaje Protegido comparten perímetro (1.621,9 ha) y la ZEC (895,6 ha) queda dentro; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Reptilia', 'Squamata', 'Phyllodactylidae', 'Tarentola', 'LC', 'LESRPE (RD 139/2011)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 11692, 2445034, NULL, NULL, NULL
