    SELECT 'Erizo moruno', 'Atelerix algirus', 'fauna', 'Mamífero', 'Matorral termomediterráneo semiárido', 'Protegida (LESRPE)', 'Erizo de orejas grandes y color claro, propio del matorral árido del sureste ibérico; nocturno e insectívoro, se refugia bajo la vegetación densa.', NULL, 'Orejas grandes y tono claro; Nocturno e insectívoro; Se ovilla ante el peligro', 'Primavera a otoño (hiberna)', 'https://commons.wikimedia.org/wiki/Special:FilePath/Erizo_moruno_(Atelerix_algirus).jpg?width=1280', 'Galanthus (CC BY 3.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE (RD 139/2011)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"En régimen de protección especial","norma":"Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011","ambito":"España"}', 0, 1, NULL, 'GBIF: 0 ocurrencias dentro de los polígonos de hábitat del espacio (0 hábitats; barrido de 2026-08-22); Plan de gestión integral de los relieves y cuencas centro-orientales, volumen II §1.2 (Decreto n.º 252/2022, BORM n.º 38 de 16.02.2023, supl. 6): la norma la enumera en el inventario conjunto del Paisaje Protegido, la ZEPA ES0000195 y la ZEC ES6200005 «Humedal del Ajauque y Rambla Salada», que el volumen II trata como un solo espacio protegido; la ZEPA y el Paisaje Protegido comparten perímetro (1.621,9 ha) y la ZEC (895,6 ha) queda dentro; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Mammalia', 'Erinaceomorpha', 'Erinaceidae', 'Atelerix', 'LC', 'LESRPE (RD 139/2011); Directiva Hábitats 92/43/CEE, Anexo IV', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 10669, 2437136, NULL, NULL, NULL
