    SELECT 'Cigüeñuela', 'Himantopus himantopus', 'fauna', 'Ave limícola', 'Salinas, marismas, charcas someras y humedales salobres', 'Protegida (LESRPE)', 'Limícola blanca y negra de patas rosadas larguísimas, desproporcionadas para su tamaño, que le permiten caminar por aguas someras picoteando insectos en la superficie. Es ruidosa y muy territorial cerca del nido, y sobrevuela en círculos a quien se acerca.', 'EIDOS (IEPNB, MITECO), v_atributos_pliniancore, atributo «Descripción de la especie»', 'Patas rojizas extremadamente largas, que sobresalen en vuelo; Contraste limpio de blanco y negro, con pico fino y recto; Reclamo insistente y chillón al sobrevolar al intruso', 'Sobre todo de primavera a verano', 'https://commons.wikimedia.org/wiki/Special:FilePath/Himantopus_himantopus.jpg?width=1280', '(Hans Hillewaert) (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, NULL, 2, '{"categoria":"En régimen de protección especial","norma":"Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011","ambito":"España"}', 0, 1, NULL, 'GBIF confirma su presencia con 213 ocurrencias dentro del espacio (barrido de 2026-08-22); las aves no se adscriben a hábitats; Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000195 (Humedal del Ajauque y Rambla Salada), sección 3.2: población reproductora; Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000195 (Humedal del Ajauque y Rambla Salada), sección 3.2: población permanente; Plan de gestión integral de los relieves y cuencas centro-orientales, volumen II §1.2 (Decreto n.º 252/2022, BORM n.º 38 de 16.02.2023, supl. 6): la norma la enumera en el inventario conjunto del Paisaje Protegido, la ZEPA ES0000195 y la ZEC ES6200005 «Humedal del Ajauque y Rambla Salada», que el volumen II trata como un solo espacio protegido; la ZEPA y el Paisaje Protegido comparten perímetro (1.621,9 ha) y la ZEC (895,6 ha) queda dentro; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Charadriiformes', 'Recurvirostridae', 'Himantopus', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2019)', 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero) · Anexo IV (Ley 42/2007, de 13 de diciembre)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 11446, 5229126, 'ES0000195', 0, '{"tipos":["permanente","reproductora"],"etiqueta":"Residente todo el año · Reproductora: cría aquí","sitios":[{"code":"ES0000195","name":"Humedal del Ajauque y Rambla Salada","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000195 (Humedal del Ajauque y Rambla Salada), sección 3.2"}'
    UNION ALL
    SELECT 'Tarro blanco', 'Tadorna tadorna', 'fauna', 'Ave acuática', NULL, 'Interés especial', 'Anátida intermedia (por forma y comportamiento) entre un ganso y un pato típicos, que presenta las patas muy centradas en el cuerpo, en una posición que facilita la acción de pastar. Su coloración general es blanca, con el dorso más oscuro (verdoso) y un ancho collar pardorrojizo en el pecho. La cabeza y el cuello son de un verde oscuro, a modo de capuchón. El pico rojo posee un llamativo abultamiento en la frente de los machos. Los jóvenes son mucho más pálidos, sin collar y sin capucha definida, con el dorso pardo escamado, cabeza y cuello oscuros, cara blanquecina y pico rosado. En vuelo, las primarias y secundarias, de color muy oscuro —las últimas de un tono verde botella—, contrastan con el tono general blanco.', 'EIDOS (IEPNB, MITECO), v_atributos_pliniancore, atributo «Descripción de la especie»', NULL, 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Common_Shelduck_(Tadorna_tadorna)_(26499348215).jpg?width=1280', 'Bernard DUPONT from FRANCE (CC BY-SA 2.0) · Wikimedia Commons', NULL, NULL, 1, NULL, 3, '{"categoria":"Especies de interés especial","norma":"Ley 7/1995, de 21 de abril, de la fauna silvestre, caza y pesca fluvial de la Región de Murcia.","ambito":"Región de Murcia"}', 0, 1, NULL, 'GBIF confirma su presencia con 178 ocurrencias dentro del espacio (barrido de 2026-08-22); las aves no se adscriben a hábitats; Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000195 (Humedal del Ajauque y Rambla Salada), sección 3.2: población permanente; Plan de gestión integral de los relieves y cuencas centro-orientales, volumen II §1.2 (Decreto n.º 252/2022, BORM n.º 38 de 16.02.2023, supl. 6): la norma la enumera en el inventario conjunto del Paisaje Protegido, la ZEPA ES0000195 y la ZEC ES6200005 «Humedal del Ajauque y Rambla Salada», que el volumen II trata como un solo espacio protegido; la ZEPA y el Paisaje Protegido comparten perímetro (1.621,9 ha) y la ZEC (895,6 ha) queda dentro; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Anseriformes', 'Anatidae', 'Tadorna', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2019)', 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)', 'Especies de interés especial (Ley 7/1995, de 21 de abril, de la fauna silvestre, caza y pesca fluvial de la Región de Murcia.)', NULL, 12286, 2498009, 'ES0000195', 0, '{"tipos":["permanente"],"etiqueta":"Residente todo el año","sitios":[{"code":"ES0000195","name":"Humedal del Ajauque y Rambla Salada","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000195 (Humedal del Ajauque y Rambla Salada), sección 3.2"}'
    UNION ALL
    SELECT 'Alcaraván', 'Burhinus oedicnemus', 'fauna', 'Ave esteparia', 'Llanos pedregosos, cultivos de secano, ramblas y eriales con poca cobertura', 'LC', 'Ave de aspecto extraño y ojos amarillos enormes, adaptados a la actividad nocturna. De día permanece agachada e inmóvil, confiada en su plumaje críptico, y solo al anochecer se activa y delata con un reclamo silbado y melancólico que recuerda al del zarapito.', NULL, 'Ojos amarillos desproporcionadamente grandes; Dos barras blancas y negras en el ala plegada; Reclamo silbado y triste al anochecer', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Burhinus_oedicnemus_insularum_Lanzarote_1.jpg?width=1280', 'Frank Vassen from Brussels, Belgium (CC BY 2.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE","ambito":"estatal","origen":"rarityScore estatal del catálogo universal: EIDOS no devolvió ninguna norma para este taxón al hacer la selección, y el tramo local no puede quedar por debajo del estatal"}', 0, 1, NULL, 'GBIF confirma su presencia con 171 ocurrencias dentro del espacio (barrido de 2026-08-22); las aves no se adscriben a hábitats; Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000195 (Humedal del Ajauque y Rambla Salada), sección 3.2: población reproductora; Plan de gestión integral de los relieves y cuencas centro-orientales, volumen II §1.2 (Decreto n.º 252/2022, BORM n.º 38 de 16.02.2023, supl. 6): la norma la enumera en el inventario conjunto del Paisaje Protegido, la ZEPA ES0000195 y la ZEC ES6200005 «Humedal del Ajauque y Rambla Salada», que el volumen II trata como un solo espacio protegido; la ZEPA y el Paisaje Protegido comparten perímetro (1.621,9 ha) y la ZEC (895,6 ha) queda dentro; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Chordata', 'Aves', 'Charadriiformes', 'Burhinidae', 'Burhinus', 'LC', 'LESRPE; Directiva Aves 2009/147/CE, Anexo I', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 11887, 2482100, 'ES0000195', 1, '{"tipos":["reproductora"],"etiqueta":"Reproductora: cría aquí","sitios":[{"code":"ES0000195","name":"Humedal del Ajauque y Rambla Salada","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000195 (Humedal del Ajauque y Rambla Salada), sección 3.2"}'
    UNION ALL
    SELECT 'Lavandera blanca', 'Motacilla alba', 'fauna', 'Ave', NULL, 'Protegida (LESRPE)', 'Pájaro estilizado de aspecto muy distintivo, con larga cola y tonos blancos, negros y grises. Exhibe dorso gris ceniza, vientre blanco, y alas negras y con bandas blancas cuando están plegadas. Posee cola larga y negra, con plumas externas blancas, y patas y pico negros. El patrón de la cabeza resulta muy contrastado, con la cara blanca rodeada arriba y abajo de negro. Luce un plumaje invernal similar, aunque el color negro en la cabeza está más reducido, y muestra garganta blanca y banda pectoral negra. La lavandera enlutada (M. a. yarrelli), de origen británico, presenta tonos negros en dorso y flancos. Ambos sexos son parecidos, pero la hembra tiene la nuca gris. Los jóvenes resultan más uniformes, sin negro en la cabeza y con banda pectoral grisácea. Un hábito destacado de esta ave es el continuo balanceo de la cola. En invierno se vuelve muy gregaria y se reúne en dormideros.', NULL, NULL, 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/White-Wagtail.jpg?width=1280', 'Andreas Trepte (CC BY-SA 2.5) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"En régimen de protección especial","norma":"Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011","ambito":"España"}', 0, 1, NULL, 'GBIF confirma su presencia con 149 ocurrencias dentro del espacio (barrido de 2026-08-22); las aves no se adscriben a hábitats; Plan de gestión integral de los relieves y cuencas centro-orientales, volumen II §1.2 (Decreto n.º 252/2022, BORM n.º 38 de 16.02.2023, supl. 6): la norma la enumera en el inventario conjunto del Paisaje Protegido, la ZEPA ES0000195 y la ZEC ES6200005 «Humedal del Ajauque y Rambla Salada», que el volumen II trata como un solo espacio protegido; la ZEPA y el Paisaje Protegido comparten perímetro (1.621,9 ha) y la ZEC (895,6 ha) queda dentro; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Passeriformes', 'Motacillidae', 'Motacilla', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2019)', 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 10648, 9687165, NULL, NULL, NULL
    UNION ALL
    SELECT 'Ánade azulón', 'Anas platyrhynchos', 'fauna', 'Ave acuática', NULL, 'LC', 'En el plumaje del macho de ánade azulón destaca el color verde brillante con irisaciones que presenta en cabeza y cuello. Un estrecho collar blanco separa a este del pecho, que es castaño. El dorso es parduzco; las partes ventrales, grises, y la popa, de color negro, resalta sobre los extremos blancos de las rectrices. El pico es amarillo con la uña negra, en tanto que las patas poseen una coloración anaranjada. Como rasgos característicos en el diseño de este ánade destacan, por un lado, las dos plumas negras y rizadas que presenta sobre la cola y, por otro, el espejuelo, de una tonalidad azul violácea —de ahí su denominación de azulón—, muy patente en vuelo. Como ocurre con la mayoría de las anátidas, esta especie presenta un acusado dimorfismo sexual. En este caso, las hembras tienen un tamaño algo menor que el del macho y son muy crípticas, con un plumaje parduzco moteado en el que tan solo resalta el espejuelo, del mismo color que en el macho. Los jóvenes muestran gran parecido con las hembras, si bien la tonalidad general es algo rojiza.', 'EIDOS (IEPNB, MITECO), v_atributos_pliniancore, atributo «Descripción de la especie»', NULL, 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/%D0%9F%D0%B0%D1%80%D0%B0_%D1%83%D1%82%D0%BE%D0%BA_%D0%BA%D1%80%D1%8F%D0%BA%D0%B2_(Anas_platyrhynchos)%2C_%D0%9A%D0%BE%D0%BB%D0%BE%D0%BC%D0%B5%D0%BD%D1%81%D0%BA%D0%BE%D0%B5.jpg?width=1280', 'Dion Art (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 1, NULL, 1, NULL, 0, 1, NULL, 'GBIF confirma su presencia con 148 ocurrencias dentro del espacio (barrido de 2026-08-22); las aves no se adscriben a hábitats; Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000195 (Humedal del Ajauque y Rambla Salada), sección 3.2: población permanente; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Chordata', 'Aves', 'Anseriformes', 'Anatidae', 'Anas', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2019)', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 12000, 9761484, 'ES0000195', 0, '{"tipos":["permanente"],"etiqueta":"Residente todo el año","sitios":[{"code":"ES0000195","name":"Humedal del Ajauque y Rambla Salada","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000195 (Humedal del Ajauque y Rambla Salada), sección 3.2"}'
    UNION ALL
    SELECT 'Cernícalo vulgar', 'Falco tinnunculus', 'fauna', 'Ave rapaz', 'Campos abiertos, matorral, cortados y también ciudades', 'Protegida (LESRPE)', 'El halcón más común y fácil de ver, gracias a su costumbre de cernirse: se queda suspendido en el aire batiendo las alas con la cabeza inmóvil, buscando ratones y lagartijas. El macho tiene la cabeza gris y el dorso rojizo con puntos negros; la hembra es más parda y barrada.', NULL, 'Se queda «clavado» en el aire cerniéndose; Dorso rojizo salpicado de puntos negros; Cola larga con una banda negra ancha en la punta', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Common_kestrel_falco_tinnunculus.jpg?width=1280', 'Andreas Trepte (CC BY-SA 2.5) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"Directiva Aves 2009/147/CE (Red Natura 2000)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"En régimen de protección especial","norma":"Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011","ambito":"España"}', 0, 1, NULL, 'GBIF confirma su presencia con 140 ocurrencias dentro del espacio (barrido de 2026-08-22); las aves no se adscriben a hábitats; Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000195 (Humedal del Ajauque y Rambla Salada), sección 3.2: población permanente, escasa; Plan de gestión integral de los relieves y cuencas centro-orientales, volumen II §1.2 (Decreto n.º 252/2022, BORM n.º 38 de 16.02.2023, supl. 6): la norma la enumera en el inventario conjunto del Paisaje Protegido, la ZEPA ES0000195 y la ZEC ES6200005 «Humedal del Ajauque y Rambla Salada», que el volumen II trata como un solo espacio protegido; la ZEPA y el Paisaje Protegido comparten perímetro (1.621,9 ha) y la ZEC (895,6 ha) queda dentro; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', NULL, NULL, 'Falco', 'LC (Preocupación menor)', 'Directiva Aves 2009/147/CE (Red Natura 2000)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 12321, 9616058, 'ES0000195', 0, '{"tipos":["permanente"],"etiqueta":"Residente todo el año","sitios":[{"code":"ES0000195","name":"Humedal del Ajauque y Rambla Salada","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000195 (Humedal del Ajauque y Rambla Salada), sección 3.2"}'
    UNION ALL
    SELECT 'Aguilucho lagunero occidental', 'Circus aeruginosus', 'fauna', 'Ave rapaz', 'Masas de vegetación palustre,lagunas, ríos y pantanos.Nidos en vegetación a pocos cm del agua,suelo', 'Extinguida', 'El aguilucho lagunero es una rapaz de tamaño medio y aspecto bastante estilizado, aunque ciertamente más robusto que los restantes aguiluchos presentes en nuestra fauna, a los que también supera en envergadura. La especie presenta, como es habitual en otros miembros del género Circus, un acusado dimorfismo sexual, ya que la hembra es bastante mayor y más pesada que el macho, y ambos sexos exhiben plumajes muy diferentes. En el macho adulto predominan los tonos marrones en el dorso, aunque la cabeza y la nuca son amarillentas o ligeramente grisáceas y surcadas por finas estrías oscuras. Las partes inferiores —especialmente a la altura de las patas y el bajo vientre— suelen adquirir un color rojizo, que va dando paso al crema o blanco sucio a medida que subimos hacia el pecho y la garganta, los cuales aparecen suavemente listados. Las rectrices y rémiges secundarias son grises; estas últimas describen una extensa banda alar, muy visible en vuelo . Ventralmente, las alas del macho son más bien claras —blancuzcas o de color gris pálido— y en ellas destacan fuertemente las negras rémiges primarias. Las hembras adultas, por su parte, resultan bastante más oscuras y menos contrastadas, en conjunto, que sus parejas, pues lucen un plumaje —tanto dorsal como ventralmente— dominado por los tonos pardoachocolatados, que en la cabeza, la garganta y los hombros son sustituidos por otros amarillentos o blanquecinos. Los ejemplares recién salidos del nido se parecen bastante a las hembras, aunque resultan más homogéneos y ligeramente más oscuros; además, solo presentan manchas más claras en la cabeza, la nuca y la garganta. Entre la librea juvenil y la de adulto existen varios plumajes de transición, que definen las diferentes edades del ave. Por otra parte, el aguilucho lagunero es una especie en la que no son infrecuentes los casos de melanismo y la aparición de diseños atípicos, lo que en ocasiones puede dificultar su identificación y propiciar las confusiones con especies de tamaño semejante.', NULL, NULL, 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Circus_aeruginosus_samiec2.jpg?width=1280', 'Artur Mikołajewski (CC BY 2.5) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 5, '{"categoria":"Extinguida","norma":"Ley 7/1995, de 21 de abril, de la fauna silvestre, caza y pesca fluvial de la Región de Murcia.","ambito":"Región de Murcia"}', 1, 1, NULL, 'GBIF confirma su presencia con 137 ocurrencias dentro del espacio (barrido de 2026-08-22); las aves no se adscriben a hábitats; Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000195 (Humedal del Ajauque y Rambla Salada), sección 3.2: población invernante, presente; Plan de gestión integral de los relieves y cuencas centro-orientales, volumen II §1.2 (Decreto n.º 252/2022, BORM n.º 38 de 16.02.2023, supl. 6): la norma la enumera en el inventario conjunto del Paisaje Protegido, la ZEPA ES0000195 y la ZEC ES6200005 «Humedal del Ajauque y Rambla Salada», que el volumen II trata como un solo espacio protegido; la ZEPA y el Paisaje Protegido comparten perímetro (1.621,9 ha) y la ZEC (895,6 ha) queda dentro; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Accipitriformes', 'Accipitridae', 'Circus', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2021)', 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero) · Anexo IV (Ley 42/2007, de 13 de diciembre)', 'Extinguida (Ley 7/1995, de 21 de abril, de la fauna silvestre, caza y pesca fluvial de la Región de Murcia.)', NULL, 11024, 2480482, 'ES0000195', 1, '{"tipos":["invernante"],"etiqueta":"Invernante: pasa aquí el invierno","sitios":[{"code":"ES0000195","name":"Humedal del Ajauque y Rambla Salada","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000195 (Humedal del Ajauque y Rambla Salada), sección 3.2"}'
    UNION ALL
    SELECT 'Alcaudón real', 'Lanius meridionalis', 'fauna', 'Ave', 'Campo abierto con matorral disperso, cables y posaderos altos', 'Protegida (LESRPE)', 'Alcaudón grande, gris por encima y con un antifaz negro que le cruza el ojo. Caza al acecho desde un posadero alto y tiene la costumbre de empalar sus presas —insectos, lagartijas, ratones— en espinas y alambres, formando pequeñas despensas.', NULL, 'Antifaz negro sobre fondo gris claro; Siempre en lo alto de un cable, poste o mata; Presas empaladas en espinos cerca de su territorio', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/S%C3%BCdlicher-Raubw%C3%BCrger_2018-01-07_0003.jpg?width=1280', 'Andreas Trepte (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"En régimen de protección especial","norma":"Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011","ambito":"España"}', 0, 1, NULL, 'GBIF confirma su presencia con 129 ocurrencias dentro del espacio (barrido de 2026-08-22); las aves no se adscriben a hábitats; Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000195 (Humedal del Ajauque y Rambla Salada), sección 3.2, que la cita como «Lanius meridionalis ([excluding koenigi])»: población permanente, común; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Passeriformes', 'Laniidae', 'Lanius', 'VU (Vulnerable) (evaluación UICN 2017)', 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011); UICN España: NT (Casi amenazado) (2004)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 16426, 7341500, 'ES0000195', 0, '{"tipos":["permanente"],"etiqueta":"Residente todo el año","sitios":[{"code":"ES0000195","name":"Humedal del Ajauque y Rambla Salada","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000195 (Humedal del Ajauque y Rambla Salada), sección 3.2"}'
    UNION ALL
    SELECT 'Andarríos grande', 'Tringa ochropus', 'fauna', 'Ave limícola', NULL, 'Protegida (LESRPE)', 'Se trata de un ave limícola de tamaño entre pequeño y mediano, de aspecto estilizado, con patas de mediana longitud que apenas sobresalen de la cola en vuelo, y pico igual a la longitud de la cabeza. Como otros andarríos, cuando está posado suele realizar un continuo movimiento de balanceo. La coloración es bastante oscura en la región dorsal, en marcado contraste con la garganta y las zonas ventrales, de color blanco. Presenta un límite nítido entre el pecho oscuro y el vientre blanco. Las patas son de color grisáceo oscuro y muestra también una ceja blanca, que es corta y solo se extiende entre el pico y el ojo. El adulto en plumaje nupcial exhibe numerosas pintas blancas en las partes superiores, que destacan notablemente sobre el fondo marrón oscuro. El píleo, el cuello y el pecho aparecen listados de marrón y blanco. Los ejemplares no reproductores presentan motas menos destacadas, de color ante apagado, el píleo apenas estriado de claro y el pecho grisáceo, con un estriado más difuso. El juvenil, por su parte, es semejante al adulto no reproductor, pero con las pintas de las partes superiores más conspicuas y con un estriado menos definido en el pecho. El andarríos grande es un ave tímida y nerviosa, a la que, normalmente, no se descubre hasta que alza el vuelo. En ese momento resulta fácil de identificar debido a su color muy oscuro, en el que resalta el obispillo blanco y el barrado transversal de la cola', 'EIDOS (IEPNB, MITECO), v_atributos_pliniancore, atributo «Descripción de la especie»', NULL, 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Green_Sandpiper_(Tringa_ochropus)-_In_Breeding_plumage_at_Bharatpur_I_IMG_5533.jpg?width=1280', 'J.M.Garg (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, NULL, 2, '{"categoria":"En régimen de protección especial","norma":"Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011","ambito":"España"}', 0, 1, NULL, 'GBIF confirma su presencia con 115 ocurrencias dentro del espacio (barrido de 2026-08-22); las aves no se adscriben a hábitats; Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000195 (Humedal del Ajauque y Rambla Salada), sección 3.2: población invernante, presente; Plan de gestión integral de los relieves y cuencas centro-orientales, volumen II §1.2 (Decreto n.º 252/2022, BORM n.º 38 de 16.02.2023, supl. 6): la norma la enumera en el inventario conjunto del Paisaje Protegido, la ZEPA ES0000195 y la ZEC ES6200005 «Humedal del Ajauque y Rambla Salada», que el volumen II trata como un solo espacio protegido; la ZEPA y el Paisaje Protegido comparten perímetro (1.621,9 ha) y la ZEC (895,6 ha) queda dentro; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Charadriiformes', 'Scolopacidae', 'Tringa', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2016)', 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 11885, 2481728, 'ES0000195', 1, '{"tipos":["invernante"],"etiqueta":"Invernante: pasa aquí el invierno","sitios":[{"code":"ES0000195","name":"Humedal del Ajauque y Rambla Salada","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000195 (Humedal del Ajauque y Rambla Salada), sección 3.2"}'
    UNION ALL
    SELECT 'Cogujada común', 'Galerida cristata', 'fauna', 'Ave', 'Cultivos, caminos, eriales y bordes de poblado con suelo desnudo', 'Protegida (LESRPE)', 'Alondra parda de cresta alta y puntiaguda, muy ligada a caminos, cunetas y descampados junto a los pueblos. Camina en vez de saltar y, al volar, deja ver el forro rojizo de las alas y la cola con los bordes canela.', NULL, 'Cresta larga y puntiaguda, casi siempre erguida; Forro de las alas rojizo, visible al levantar el vuelo; Camina por el suelo en vez de saltar', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Crested_Lark_-_Qatar.jpg?width=1280', 'Ashraf Kotb (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE (RD 139/2011)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"En régimen de protección especial","norma":"Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011","ambito":"España"}', 0, 1, NULL, 'GBIF confirma su presencia con 113 ocurrencias dentro del espacio (barrido de 2026-08-22); las aves no se adscriben a hábitats; Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000195 (Humedal del Ajauque y Rambla Salada), sección 3.2: población permanente, común; Plan de gestión integral de los relieves y cuencas centro-orientales, volumen II §1.2 (Decreto n.º 252/2022, BORM n.º 38 de 16.02.2023, supl. 6): la norma la enumera en el inventario conjunto del Paisaje Protegido, la ZEPA ES0000195 y la ZEC ES6200005 «Humedal del Ajauque y Rambla Salada», que el volumen II trata como un solo espacio protegido; la ZEPA y el Paisaje Protegido comparten perímetro (1.621,9 ha) y la ZEC (895,6 ha) queda dentro; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Passeriformes', 'Alaudidae', 'Galerida', 'LC', 'LESRPE (RD 139/2011); Directiva Aves 2009/147/CE', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 11102, 2490669, 'ES0000195', 0, '{"tipos":["permanente"],"etiqueta":"Residente todo el año","sitios":[{"code":"ES0000195","name":"Humedal del Ajauque y Rambla Salada","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000195 (Humedal del Ajauque y Rambla Salada), sección 3.2"}'
    UNION ALL
    SELECT 'Gallineta común', 'Gallinula chloropus', 'fauna', 'Ave acuática', NULL, 'LC', 'La coloración de este rálido de mediano tamaño a cierta distancia parece uniformemente oscura, casi negra, aunque visto de cerca se puede apreciar cómo el dorso adquiere una tonalidad entre verdosa y olivácea, con abundantes brillos metálicos, mientras que la cabeza es de un intenso color pizarra, que se va tornando azulado a medida que alcanza la nuca. Las regiones inferiores del ave son de color gris oscuro, si bien los flancos resultan prácticamente negros y aparecen ribeteados por largas plumas blancas que definen una llamativa línea discontinua. De color blanco también son las infracoberteras caudales, las cuales dibujan un conspicuo parche que contrasta fuertemente con el resto del plumaje; esta región de la anatomía de la gallineta —denominada escudo anal— es usada como indicador de los estados de ánimo y a modo de mecanismo de comunicación intraespecífica. Las zonas desnudas de la gallineta común resultan también ciertamente llamativas y sufren algunas modificaciones durante la etapa de reproducción, en que se tornan más brillantes. Así, el iris —normalmente marronáceo— adquiere un intenso color carmesí; las patas toman una coloración amarillenta, que se transforma en roja en la mitad superior de la tibia, y el escudete frontal, al igual que el pico, adquiere una intensa tonalidad roja en fuerte contraste con la punta amarilla de este. Las gallinetas jóvenes, al contrario que los adultos, lucen una librea bastante modesta, en la que dominan los tonos marronáceos con tintes verdosos; además, carecen de escudete frontal y de los restantes ornamentos cromáticos propios de las aves maduras.', 'EIDOS (IEPNB, MITECO), v_atributos_pliniancore, atributo «Descripción de la especie»', NULL, 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Common_Moorhen_(Gallinella_d''Acqua)_(Gallinula_chloropus)_-_Cagliari%2C_Italy_2024-03-30.jpg?width=1280', 'Ryan Hodnett (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 1, NULL, 1, NULL, 0, 1, NULL, 'GBIF confirma su presencia con 109 ocurrencias dentro del espacio (barrido de 2026-08-22); las aves no se adscriben a hábitats; Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000195 (Humedal del Ajauque y Rambla Salada), sección 3.2: población permanente, común; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Chordata', 'Aves', 'Gruiformes', 'Rallidae', 'Gallinula', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2019)', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 10887, 5228199, 'ES0000195', 0, '{"tipos":["permanente"],"etiqueta":"Residente todo el año","sitios":[{"code":"ES0000195","name":"Humedal del Ajauque y Rambla Salada","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000195 (Humedal del Ajauque y Rambla Salada), sección 3.2"}'
    UNION ALL
    SELECT 'Golondrina común', 'Hirundo rustica', 'fauna', 'Ave', NULL, 'Protegida (LESRPE)', 'Ave delicada, grácil y aerodinámica, de color negro, con reflejos azules metálicos por arriba y blancos crema en las partes inferiores. Tiene la frente y la garganta rojas y un collar negro. Las alas, largas y apuntadas, muestran tonos blancos en la parte inferior delantera. Su cola, muy larga y ahorquillada, es de color negro, con pequeños óvalos blancos cuando la extiende. Posee patas cortas sin emplumar, boca muy ancha, y pico corto, plano y negro. Presenta variación latitudinal en el tamaño corporal y en la longitud de la cola, que son menores hacia el sur. Aunque ambos sexos se parecen, la hembra es menos brillante, más blanca por abajo y con la cola más corta. Los jóvenes lucen tonos negros mate, tienen la frente y la garganta naranjas y una cola mucho más corta. De vuelo ágil, rápido y acrobático, la golondrina común ocupa en el espacio aéreo las capas bajas, por debajo de aviones y vencejos.', NULL, NULL, 'Marzo a octubre', 'https://commons.wikimedia.org/wiki/Special:FilePath/Landsvale.jpg?width=1280', 'Malene Thyssen (CC BY 2.5) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"En régimen de protección especial","norma":"Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011","ambito":"España"}', 0, 1, NULL, 'GBIF confirma su presencia con 105 ocurrencias dentro del espacio (barrido de 2026-08-22); las aves no se adscriben a hábitats; Plan de gestión integral de los relieves y cuencas centro-orientales, volumen II §1.2 (Decreto n.º 252/2022, BORM n.º 38 de 16.02.2023, supl. 6): la norma la enumera en el inventario conjunto del Paisaje Protegido, la ZEPA ES0000195 y la ZEC ES6200005 «Humedal del Ajauque y Rambla Salada», que el volumen II trata como un solo espacio protegido; la ZEPA y el Paisaje Protegido comparten perímetro (1.621,9 ha) y la ZEC (895,6 ha) queda dentro; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Passeriformes', 'Hirundinidae', 'Hirundo', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2019)', 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 12134, 9515886, NULL, NULL, NULL
    UNION ALL
    SELECT 'Cetia ruiseñor', 'Cettia cetti', 'fauna', 'Ave', NULL, 'Protegida (LESRPE)', 'Se trata de un pájaro de pequeño tamaño, de diseño muy discreto y aspecto rechoncho, con alas y cola redondeadas. Presenta el dorso de color pardo-rojizo oscuro y las zonas inferiores grisáceas, con motas claras en las infracoberteras caudales. Posee una ceja pálida, así como una zona auricular grisácea y un pico muy fino. Ambos sexos son iguales en apariencia y solamente se diferencian por pequeñas variaciones de tamaño. De hábitos escondidizos, resulta difícil de observar, pero es, en cambio, muy fácil de detectar en las espesas marañas ribereñas que frecuenta por su inconfundible y sonoro canto. Cuando se desplaza entre la vegetación, levanta y despliega frecuentemente la cola.', NULL, NULL, 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/37-090505-cettis-warbler-at-Kalloni-east-river.jpg?width=1280', 'Mark S Jobling (CC BY 3.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"En régimen de protección especial","norma":"Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011","ambito":"España"}', 0, 1, NULL, 'GBIF confirma su presencia con 98 ocurrencias dentro del espacio (barrido de 2026-08-22); las aves no se adscriben a hábitats; Plan de gestión integral de los relieves y cuencas centro-orientales, volumen II §1.2 (Decreto n.º 252/2022, BORM n.º 38 de 16.02.2023, supl. 6): la norma la enumera en el inventario conjunto del Paisaje Protegido, la ZEPA ES0000195 y la ZEC ES6200005 «Humedal del Ajauque y Rambla Salada», que el volumen II trata como un solo espacio protegido; la ZEPA y el Paisaje Protegido comparten perímetro (1.621,9 ha) y la ZEC (895,6 ha) queda dentro; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Passeriformes', 'Cettiidae', 'Cettia', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2017)', 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 11003, 2493012, NULL, NULL, NULL
    UNION ALL
    SELECT 'Mosquitero común', 'Phylloscopus collybita', 'fauna', 'Ave', NULL, 'Protegida (LESRPE)', 'Se trata de un pequeño pajarillo de pico fino y patas oscuras. Presenta tonos verdosos o pardo-grisáceos en el dorso y blanquecinos en las partes inferiores. Ambos sexos resultan similares, si bien los machos son ligeramente mayores que las hembras. Es una especie prácticamente idéntica en el campo al mosquitero ibérico, del que se distingue por su canto y por encontrarse presente en nuestro territorio durante todo el año o en invierno —según las regiones—, mientras que el ibérico es un ave únicamente estival. Es también muy similar al mosquitero musical, pero este posee las patas y el pico pálidos, así como la lista superciliar y otras finas marcas auriculares más definidas. Además, el musical solo está presente en paso.', NULL, NULL, 'Octubre a abril', 'https://commons.wikimedia.org/wiki/Special:FilePath/Chiffchaff_-_Phylloscopus_collybita.jpg?width=1280', 'Andreas Trepte (CC BY-SA 2.5) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"En régimen de protección especial","norma":"Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011","ambito":"España"}', 0, 1, NULL, 'GBIF confirma su presencia con 96 ocurrencias dentro del espacio (barrido de 2026-08-22); las aves no se adscriben a hábitats; Plan de gestión integral de los relieves y cuencas centro-orientales, volumen II §1.2 (Decreto n.º 252/2022, BORM n.º 38 de 16.02.2023, supl. 6): la norma la enumera en el inventario conjunto del Paisaje Protegido, la ZEPA ES0000195 y la ZEC ES6200005 «Humedal del Ajauque y Rambla Salada», que el volumen II trata como un solo espacio protegido; la ZEPA y el Paisaje Protegido comparten perímetro (1.621,9 ha) y la ZEC (895,6 ha) queda dentro; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Passeriformes', 'Phylloscopidae', 'Phylloscopus', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2019)', 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 11056, 2493091, NULL, NULL, NULL
    UNION ALL
    SELECT 'Garceta común', 'Egretta garzetta', 'fauna', 'Ave acuática', 'Marismas, salinas, ramblas con agua, arrozales y orillas costeras', 'Protegida (LESRPE)', 'Garza blanca y esbelta, de tamaño medio, con el pico negro y las patas negras rematadas en unos pies amarillos llamativos. Pesca removiendo el fondo con esas patas para levantar peces y camarones. En época de cría luce dos plumas largas y finas en la nuca.', NULL, 'Pies amarillos al final de patas negras; Pico negro y fino, no amarillo; Remueve el fondo con una pata mientras acecha', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Aigrette_garzette_au_lac_sud_de_Tunis_(site_RAMSAR).jpg?width=1280', 'El Golli Mohamed (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"Directiva Aves 2009/147/CE (Red Natura 2000)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"En régimen de protección especial","norma":"Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011","ambito":"España"}', 0, 1, NULL, 'GBIF confirma su presencia con 93 ocurrencias dentro del espacio (barrido de 2026-08-22); las aves no se adscriben a hábitats; Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000195 (Humedal del Ajauque y Rambla Salada), sección 3.2: población permanente; Plan de gestión integral de los relieves y cuencas centro-orientales, volumen II §1.2 (Decreto n.º 252/2022, BORM n.º 38 de 16.02.2023, supl. 6): la norma la enumera en el inventario conjunto del Paisaje Protegido, la ZEPA ES0000195 y la ZEC ES6200005 «Humedal del Ajauque y Rambla Salada», que el volumen II trata como un solo espacio protegido; la ZEPA y el Paisaje Protegido comparten perímetro (1.621,9 ha) y la ZEC (895,6 ha) queda dentro; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', NULL, NULL, 'Egretta', 'LC (Preocupación menor)', 'Directiva Aves 2009/147/CE (Red Natura 2000)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 11340, 2480876, 'ES0000195', 0, '{"tipos":["permanente"],"etiqueta":"Residente todo el año","sitios":[{"code":"ES0000195","name":"Humedal del Ajauque y Rambla Salada","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000195 (Humedal del Ajauque y Rambla Salada), sección 3.2"}'
