    SELECT 'Tarabilla europea', 'Saxicola rubicola', 'fauna', 'Ave', 'Matorral bajo, herbazales, ribazos y bordes de cultivo con posaderos', 'Protegida (LESRPE)', 'Pájaro pequeño y regordete que se posa en lo alto de las matas, muy erguido y a la vista, para lanzarse al suelo a por insectos. El macho tiene la cabeza negra, un collar blanco a los lados y el pecho naranja. Su reclamo suena como dos piedras golpeadas, de donde le viene el nombre.', NULL, 'Siempre en lo alto de una mata, bien visible; Macho con capucha negra y medio collar blanco; Reclamo como el chasquido de dos cantos rodados', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Malestonechatseaham_Cropped.jpg?width=1280', 'derivative work: Myosotis Scorpioides (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"Listado de Especies Silvestres en Régimen de Protección Especial (LESRPE)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"En régimen de protección especial","norma":"Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011","ambito":"España"}', 0, 1, NULL, 'GBIF confirma su presencia con 93 ocurrencias dentro del espacio (barrido de 2026-08-22); las aves no se adscriben a hábitats; Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000195 (Humedal del Ajauque y Rambla Salada), sección 3.2, que la cita como «Saxicola torquatus»: población reproductora, presente; Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000195 (Humedal del Ajauque y Rambla Salada), sección 3.2, que la cita como «Saxicola torquatus»: población permanente, presente; Plan de gestión integral de los relieves y cuencas centro-orientales, volumen II §1.2 (Decreto n.º 252/2022, BORM n.º 38 de 16.02.2023, supl. 6): la norma la enumera en el inventario conjunto del Paisaje Protegido, la ZEPA ES0000195 y la ZEC ES6200005 «Humedal del Ajauque y Rambla Salada», que el volumen II trata como un solo espacio protegido; la ZEPA y el Paisaje Protegido comparten perímetro (1.621,9 ha) y la ZEC (895,6 ha) queda dentro, que la cita como «Saxicola torquata» (migradora de llegada regular no incluida en el Anexo I de la Directiva Aves); EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Passeriformes', 'Muscicapidae', 'Saxicola', 'LC (Preocupación menor)', 'Listado de Especies Silvestres en Régimen de Protección Especial (LESRPE)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 16387, 4408759, 'ES0000195', 0, '{"tipos":["permanente","reproductora"],"etiqueta":"Residente todo el año · Reproductora: cría aquí","sitios":[{"code":"ES0000195","name":"Humedal del Ajauque y Rambla Salada","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000195 (Humedal del Ajauque y Rambla Salada), sección 3.2"}'
    UNION ALL
    SELECT 'Abejaruco europeo', 'Merops apiaster', 'fauna', 'Ave', 'Matorral termomediterráneo semiárido', 'Protegida (LESRPE)', 'Ave colorida y gregaria que caza abejas y libélulas en vuelo sobre espacios abiertos y cría en galerías excavadas en taludes terrosos.', NULL, 'Colorido inconfundible; Reclamo ''prruip'' en vuelo; Cría en taludes de rambla', 'Primavera y verano (estival)', 'https://commons.wikimedia.org/wiki/Special:FilePath/%C5%9Eahl%C3%BBr-33.jpg?width=1280', 'Dûrzan cîrano (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE (RD 139/2011)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"En régimen de protección especial","norma":"Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011","ambito":"España"}', 0, 1, NULL, 'GBIF confirma su presencia con 86 ocurrencias dentro del espacio (barrido de 2026-08-22); las aves no se adscriben a hábitats; Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000195 (Humedal del Ajauque y Rambla Salada), sección 3.2: población reproductora, presente; Plan de gestión integral de los relieves y cuencas centro-orientales, volumen II §1.2 (Decreto n.º 252/2022, BORM n.º 38 de 16.02.2023, supl. 6): la norma la enumera en el inventario conjunto del Paisaje Protegido, la ZEPA ES0000195 y la ZEC ES6200005 «Humedal del Ajauque y Rambla Salada», que el volumen II trata como un solo espacio protegido; la ZEPA y el Paisaje Protegido comparten perímetro (1.621,9 ha) y la ZEC (895,6 ha) queda dentro; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Coraciiformes', 'Meropidae', 'Merops', 'LC', 'LESRPE (RD 139/2011)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 10738, 2475443, 'ES0000195', 1, '{"tipos":["reproductora"],"etiqueta":"Reproductora: cría aquí","sitios":[{"code":"ES0000195","name":"Humedal del Ajauque y Rambla Salada","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000195 (Humedal del Ajauque y Rambla Salada), sección 3.2"}'
