    SELECT 'Roquero solitario', 'Monticola solitarius', 'fauna', 'Ave', 'Acantilados mediterráneos con Limonium', 'Protegida (LESRPE)', 'Pájaro rupícola de plumaje azul pizarra en el macho, ligado a acantilados marinos y roquedos, donde canta desde cornisas destacadas.', NULL, 'Macho azul pizarra; Canta desde cornisas y cumbres; Acantilados y roquedos calcáreos', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Blue_rock_thrush_(male)_at_Gamla_Nature_Reserve.jpg?width=1280', 'Artemy Voikhansky (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial, RD 139/2011)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"En régimen de protección especial","norma":"Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011","ambito":"España"}', 0, 1, NULL, 'GBIF confirma su presencia con 4 ocurrencias dentro del espacio (barrido de 2026-08-22); las aves no se adscriben a hábitats; Plan de gestión integral de los relieves y cuencas centro-orientales, volumen II §1.2 (Decreto n.º 252/2022, BORM n.º 38 de 16.02.2023, supl. 6): la norma la enumera en el inventario conjunto del Paisaje Protegido, la ZEPA ES0000195 y la ZEC ES6200005 «Humedal del Ajauque y Rambla Salada», que el volumen II trata como un solo espacio protegido; la ZEPA y el Paisaje Protegido comparten perímetro (1.621,9 ha) y la ZEC (895,6 ha) queda dentro; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Passeriformes', 'Muscicapidae', 'Monticola', 'LC', 'LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial, RD 139/2011)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 12226, 2490955, NULL, NULL, NULL
