    UNION ALL
    SELECT 'Colirrojo real', 'Phoenicurus phoenicurus', 'fauna', 'Ave', 'Bosques abiertos, sotos y arboledas con huecos para criar', 'Vulnerable', 'Pájaro elegante con la cola de un naranja encendido que hace vibrar sin parar al posarse. El macho tiene la garganta negra, la frente blanca y el pecho anaranjado; la hembra es parda pero conserva la misma cola vibrante, que es la mejor pista para identificarlos.', NULL, 'Cola naranja que tiembla constantemente; Macho con frente blanca y garganta negra; Se posa en ramas bajas y baja al suelo a por insectos', 'Paso migratorio', 'https://commons.wikimedia.org/wiki/Special:FilePath/Common_Redstart_-_Segrate_-_Italy_S4E2518-1_(19357313382).jpg?width=1280', 'Francesco Veronesi from Italy (CC BY-SA 2.0) · Wikimedia Commons', NULL, NULL, 4, '{"categoria":"CEEA: Vulnerable (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 4, '{"categoria":"Vulnerable","norma":"Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011","ambito":"España"}', 1, 1, NULL, 'GBIF confirma su presencia con 0 ocurrencias dentro del espacio (barrido de 2026-08-22); las aves no se adscriben a hábitats; Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000195 (Humedal del Ajauque y Rambla Salada), sección 3.2: población en concentración, presente; Plan de gestión integral de los relieves y cuencas centro-orientales, volumen II §1.2 (Decreto n.º 252/2022, BORM n.º 38 de 16.02.2023, supl. 6): la norma la enumera en el inventario conjunto del Paisaje Protegido, la ZEPA ES0000195 y la ZEC ES6200005 «Humedal del Ajauque y Rambla Salada», que el volumen II trata como un solo espacio protegido; la ZEPA y el Paisaje Protegido comparten perímetro (1.621,9 ha) y la ZEC (895,6 ha) queda dentro, con la categoría «Vulnerable (Catálogo Español de Especies Amenazadas)»; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Passeriformes', 'Muscicapidae', 'Phoenicurus', 'LC (Preocupación menor) (evaluación UICN 2019)', 'CEEA: Vulnerable (Real Decreto 139/2011, de 4 de febrero)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 11977, 5739317, 'ES0000195', 1, '{"tipos":["en concentración"],"etiqueta":"En paso migratorio","sitios":[{"code":"ES0000195","name":"Humedal del Ajauque y Rambla Salada","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000195 (Humedal del Ajauque y Rambla Salada), sección 3.2"}'
