-- ------------------------------------------------------------------------------------------------
-- 5. Comprobación posterior. Debe devolver exactamente los recuentos de la cabecera.
-- ------------------------------------------------------------------------------------------------
SELECT
    (SELECT COUNT(*) FROM parks WHERE slug = 'humedal-del-ajauque-y-rambla-salada') AS espacio,
    (SELECT COUNT(*) FROM habitats h JOIN parks p ON p.id = h.park_id WHERE p.slug = 'humedal-del-ajauque-y-rambla-salada') AS habitats,
    (SELECT COUNT(*) FROM species s JOIN parks p ON p.id = s.park_id WHERE p.slug = 'humedal-del-ajauque-y-rambla-salada') AS especies,
    (SELECT COUNT(*) FROM species_habitats sh JOIN species s ON s.id = sh.species_id JOIN parks p ON p.id = s.park_id WHERE p.slug = 'humedal-del-ajauque-y-rambla-salada') AS vinculos;
